110	+
111	+/* Trạng thái ban đầu tại điểm cất cánh */
112	+export function exCreate(): GliderState {
113	+  return { pos: new THREE.Vector3(C.takeoff[0], C.takeoff[1], C.takeoff[2]), yaw: C.takeoffYaw, bank: 0 };
114	+}
115	+
116	+const wrapPi = (a: number) => Math.atan2(Math.sin(a), Math.cos(a));
117	+
118	+/* Lái về tâm khung khi sát mép: trả hướng rẽ hiệu lực (−1..1) thay cho phím người chơi */
119	+function exTurnEff(s: GliderState, turn: number): number {
120	+  const b = C.bounds, m = C.returnMargin;
121	+  const d = Math.min(s.pos.x - b.x0, b.x1 - s.pos.x, s.pos.z - b.z0, b.z1 - s.pos.z);   // khoảng cách ngắn nhất tới mép khung
122	+  if (d >= m) return turn;
123	+  const tx = (b.x0 + b.x1) / 2 - s.pos.x, tz = (b.z0 + b.z1) / 2 - s.pos.z, tl = Math.hypot(tx, tz) || 1;
124	+  const dot = (Math.cos(s.yaw) * tx - Math.sin(s.yaw) * tz) / tl;   // hướng bay · hướng tới tâm
125	+  if (dot >= 0.3) return turn;   // đang bay vào trong: giữ phím người chơi
126	+  const delta = wrapPi(Math.atan2(-tz, tx) - s.yaw);   // yaw hướng tâm − yaw hiện tại
127	+  const sg = delta >= 0 ? 1 : -1;
128	+  if (d <= 0.25 * m) return sg;
129	+  const w = 1 - d / m;
130	+  return turn + (sg - turn) * w;
131	+}
132	+
133	+/* Một bước mô phỏng: không cấp phát */
134	+export function exStep(s: GliderState, inp: GliderInput, dt: number): void {
135	+  const turn = exTurnEff(s, inp.turn);
136	+  s.bank += (turn * C.bankMax - s.bank) * Math.min(1, C.bankRate * dt);
137	+  s.yaw += C.turnRate * (s.bank / C.bankMax) * dt;
138	+  s.pos.x += Math.cos(s.yaw) * C.speed * dt;
139	+  s.pos.z -= Math.sin(s.yaw) * C.speed * dt;
140	+  s.pos.y = Math.min(C.ceiling, Math.max(C.floor, s.pos.y + inp.climb * C.climbRate * dt));
141	+  const b = C.bounds;   // kẹp cứng: không bao giờ vượt khung
142	+  s.pos.x = Math.min(b.x1, Math.max(b.x0, s.pos.x));
143	+  s.pos.z = Math.min(b.z1, Math.max(b.z0, s.pos.z));
144	+}
