146	+/* Phím giữ → đầu vào lái: A/← trái, D/→ phải, W/↑ lên, S/↓ xuống; hai phím ngược nhau triệt tiêu */
147	+export function exInputFromKeys(keys: Set<string>): GliderInput {
148	+  const turn = (keys.has('a') || keys.has('arrowleft') ? 1 : 0) - (keys.has('d') || keys.has('arrowright') ? 1 : 0);
149	+  const climb = (keys.has('w') || keys.has('arrowup') ? 1 : 0) - (keys.has('s') || keys.has('arrowdown') ? 1 : 0);
150	+  return { turn: turn as -1 | 0 | 1, climb: climb as -1 | 0 | 1 };
